keyframes.css:
@keyframes sprite-frames { 
  0% { background-position: 0px 0px; }
  100% { background-position: -103.688rem 0px; }
}

@keyframes shake { 
  0% { transform: scale(1) translateY(0px); }
  10% { transform: scale(0.8, 1.2) translateY(-0.875rem); }
  20% { transform: scale(1.2, 0.8) translateY(0px); }
  30% { transform: scale(0.95, 1.05) translateY(-0.375rem); }
  40% { transform: scale(1) translateY(0px); }
  100% { transform: scale(1) translateY(0px); }
}

@keyframes drawCircle { 
  0% { stroke-dasharray: 157; stroke-dashoffset: 157; opacity: 0; }
  100% { stroke-dasharray: 157; stroke-dashoffset: 0; opacity: 1; }
}

@keyframes rotateLogo { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes eTYjOB { 
  0%, 100% { transform: rotate(0deg); }
  25% { transform: rotate(3deg); }
  50% { transform: rotate(-3deg); }
  75% { transform: rotate(1deg); }
}

@keyframes hTTapO { 
  0% { transform: scale(1) translateY(0px); }
  10% { transform: scale(0.8, 1.2) translateY(-0.875rem); }
  20% { transform: scale(1.2, 0.8) translateY(0px); }
  30% { transform: scale(0.95, 1.05) translateY(-0.375rem); }
  40% { transform: scale(1) translateY(0px); }
  100% { transform: scale(1) translateY(0px); }
}

@keyframes lkkowY { 
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-0.625rem); }
}

@keyframes drawCircle { 
  0% { stroke-dasharray: 157; stroke-dashoffset: 157; opacity: 0; }
  100% { stroke-dasharray: 157; stroke-dashoffset: 0; opacity: 1; }
}

@keyframes rotateLogo { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes drawCircle { 
  0% { stroke-dasharray: 157; stroke-dashoffset: 157; opacity: 0; }
  100% { stroke-dasharray: 157; stroke-dashoffset: 0; opacity: 1; }
}

@keyframes rotateLogo { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

cssRules:
@media (max-width: 1024px) {
  .bSlSCc { margin-bottom: 3rem; opacity: 1; transform: translateY(0px); }
}

@media (max-width: 1024px) {
  .gvzNjT { height: auto; opacity: 1; transform: none; }
}

@media (max-width: 1024px) {
  .jvorUf { position: relative; height: auto; transition: transform 0.5s; transform: none !important; }
}

